// <auto-generated/>
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Forms;
using MudBlazor;
using Recruiting.Shared.DTOs;

namespace Recruiting.Client.Components.Dialogs
{
    public partial class UploadResumeDialog
    {
        [CascadingParameter]
        private IMudDialogInstance MudDialog { get; set; } = null!;

        private IBrowserFile? _selectedFile;
        private bool _isUploading;
        private UploadResumeResponse? _uploadResponse;
        private ResumeFileDTO? _uploadedFileDto;

        private void OnFileSelected(IBrowserFile file)
        {
            _selectedFile = file;
        }

        private async Task UploadAsync()
        {
            if (_selectedFile == null) return;

            _isUploading = true;
            var (resp, err) = await ResumeClient.UploadResumeAsync(_selectedFile);
            _isUploading = false;

            if (err != null)
            {
                Snackbar.Add(err, Severity.Error);
                return;
            }

            _uploadResponse = resp;
            if (resp != null)
            {
                await RefreshStatusAsync();
            }
        }

        private async Task RefreshStatusAsync()
        {
            if (_uploadResponse == null) return;
            _uploadedFileDto = await ResumeClient.GetByIdAsync(_uploadResponse.ResumeFileId);
            StateHasChanged();
        }

        private Color GetStatusColor(string? status) => status switch
        {
            "Готово" => Color.Success,
            "Ошибка" => Color.Error,
            "В работе" => Color.Info,
            _ => Color.Warning
        };

        private void Cancel() => MudDialog.Cancel();
    }
}
